                }
            }
            if needs_flush {
                let mut ring_ref = ring.borrow_mut();
                let mut guest = ring_ref.producer();
                guest.begin_frame();
                engine.borrow_mut().emit(&tree, &mut guest).ok();
                guest.end_frame();
            }
        }
    });
}

