package dev.pathland.view;

import dev.pathland.view.emit.PathlandNode;

/**
 * A composable view. Composite views declare their subtree with
 * {@link #body()}; the library's primitives (leaves, stacks, controls) instead override
 * {@link #render(Environment)} to materialize a {@link PathlandNode}. The interface is
 * open: the library ships the leaf primitives and modifier wrappers, and application
 * code (Quarkus, Spring Boot, desktop) defines its own views by implementing
 * {@code View} directly.
 *
 * <p>{@link #body()} is evaluated once at mount — reactivity comes from signals
 * ({@code Text.make(t -> t.text(Signal))}, {@code Signals.computed}), not from body
 * re-evaluation.
 *
 * <p>Modifiers are {@link ViewModifier} values applied with {@link #modifiers(ViewModifier...)}
 * — built-in and application-authored modifiers share one mechanism (spec DSL.md
 * §5.6), applied innermost-first. There is no per-modifier factory sugar on this
 * interface. Constructor (structural/layout) properties are passed to the view
 * constructors and are never chainable.
 */
public interface View {

    /**
     * The base marker for a view's **value config** ({@code V.Config}). The
     * config is populated by the static {@code View.make(Consumer<Config>)}
     * factory and is the same type a style's {@code makeBody(Config)} reads
     * (spec DSL.md §5.7).
     */
    interface Config {
    }

    /**
     * Declarative composition: a composite view returns its subtree here. Primitives
     * return {@code this} (the identity body) and instead override
     * {@link #render(Environment)}.
     */
    default View body() {
        return this;
    }

    /**
     * Materialize this view into retained node(s). Composite views resolve
     * {@link #body()} first (recursively); primitives override this to build a
     * {@link PathlandNode}.
     */
    default PathlandNode render(Environment env) {
        dev.pathland.view.state.PersistentState state = env.state();
        if (state != null) {
            state.connect(this); // wire this view's State fields (idempotent)
        }
        View resolved = body();
        if (resolved != this) {
            return resolved.render(env);
        }
        throw new UnsupportedOperationException(
                getClass().getName() + " must override body() (composite) or render() (primitive)");
    }

    /**
     * Wrap this view in one or more modifiers ({@code .modifier}), applied
     * innermost-first: {@code modifiers(A, B, C)} ≡ {@code modifiers(A).modifiers(B).modifiers(C)}.
     * A single modifier is the common case; an empty call returns {@code this}.
     * {@code with(...)} is for values only — modifiers always go through this
     * {@code modifiers(...)} operation.
     */
    default View modifiers(ViewModifier... modifiers) {
        View result = this;
        for (ViewModifier modifier : modifiers) {
            result = Modified.apply(result, modifier);
        }
        return result;
    }
}

public RenderResult mount(View root, Environment env) {
    if (mounted) {
        throw new IllegalStateException("Emitter already mounted; create a new Emitter per tree");
    }
    mounted = true;
    this.env = env;

    // A full-snapshot (SSR) emission renders fit slots with ALL candidates so
    // the web SSR shows every branch (CSS container queries gate the first
    // paint); the live reconcile path keeps one child. The flag is scoped to
    // this render via a thread-local read by SizeThatFits.FitSlot.
    boolean prevSnapshot = PathlandNode.SNAPSHOT_EMISSION.get();
    PathlandNode.SNAPSHOT_EMISSION.set(snapshotEmission);
    PathlandNode tree;
    try {
        tree = root.render(env);
    } finally {
        PathlandNode.SNAPSHOT_EMISSION.set(prevSnapshot);
    }
    this.tree = tree;
    nextId = 1;
    assignIds(tree);
    // Materialize one non-visual `MEDIA_CONTROLLER` node per referenced
    // MediaController (spec/MEDIA.md) and bind each `VIDEO` surface to it.
    // The controller nodes are prepended so they are emitted before any
    // surface references them (a forward reference would render blank).
    mediaControllers.clear();
    mediaControllerIds.clear();
    materializeControllers(tree);
    guardUniqueIds();
    tapActions.clear();
    textInputs.clear();
    valueInputs.clear();
    editingInputs.clear();
    dateInputs.clear();
    mediaInputs.clear();
    fitInputs.clear();
    navigateActions.clear();
    proxyViews.clear();
    navigateHandler = null;
    collectInputs(tree);

    sink.beginFrame();
    emitTheme();
    emitNode(tree);
    sink.endFrame();

    bindings.clear();
    nodeBindings.clear();
    registerBindings(tree);
    rootId = tree.id;
    return new RenderResult(
            rootId,
            Collections.unmodifiableMap(tapActions),
            Collections.unmodifiableMap(textInputs),
            Collections.unmodifiableMap(valueInputs),
            Collections.unmodifiableMap(editingInputs),
            Collections.unmodifiableMap(dateInputs),
            Collections.unmodifiableMap(mediaInputs),
            Collections.unmodifiableMap(fitInputs),
            Collections.unmodifiableMap(navigateActions),
            navigateHandler,
            Collections.unmodifiableMap(proxyViews));
}

/** The root node id (0 until mounted). */
public int rootId() {
    return rootId;
}

/**
 * Re-emit the complete retained tree as one full-snapshot frame (TREE + PARAMETER).
 * Used for {@code META::RESYNC} (reconnect/gap recovery) and no-JS refresh. Does
 * not re-mount or re-wire state — it replays the current tree through the sink.
 */
public void renderFull() {
    if (!mounted) {
        throw new IllegalStateException("Emitter not mounted");
    }
    guardUniqueIds();
    sink.beginFrame();
    emitTheme();
    // The retained tree already carries every fit candidate when the session
    // mounted in snapshot mode; re-emit it as-is (a resync re-establishes the
    // container-query first paint for a reconnecting client). Before the first
    // FIT_CHANGED the tree IS the snapshot form (every candidate): the client
    // reuses its SSR gate (candidate wrappers + `@container` band rules) so the
    // width-correct candidate stays shown — a resync must NOT collapse it
    // (issue #141, spec/PRIMITIVES.md §SizeThatFits).
    emitNode(tree);
    sink.endFrame();
}

/** Emit the global theme overrides at the start of a full frame. */
private void emitTheme() {
    if (theme != null) {
        theme.emitInto(sink);
    }
}

/**
 * Replace the global theme at runtime: emits one frame with
 * {@code META::RESET_THEME} followed by the new theme's overrides
 * (spec/TOKENS.md §Runtime theming). The renderer re-resolves token
 * references; no node is re-emitted. A {@code null} theme clears all
 * overrides.
